import React from "react";

const amountOptions = ["$50", "$100", "$150", "$200", "$250"];

const inputClass =
  "tw-mt-2 tw-w-full tw-rounded-xl tw-border tw-border-solid tw-border-[#ebe7f0] tw-bg-white tw-px-4 tw-py-3 tw-text-[15px] tw-text-[#14101c] tw-outline-none focus:tw-border-[#854ec9] focus:tw-ring-2 focus:tw-ring-[#854ec9]/20";

const labelClass = "tw-text-[14px] tw-font-semibold tw-text-[#14101c]";

const CustomGiftCard = () => {
  return (
    <main className="tw-font-display tw-bg-white">
      {/* Hero */}
      <section className="tw-relative tw-overflow-hidden">
        <div
          className="tw-absolute tw-inset-0"
          style={{
            background: "linear-gradient(125deg, #4f2d7f 0%, #854ec9 100%)",
          }}
          aria-hidden="true"
        />
        <div className="tw-relative tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-py-16 md:tw-py-20 tw-text-center">
          <h1 className="tw-text-[clamp(30px,4.5vw,48px)] tw-font-bold tw-tracking-tight tw-leading-[1.1] tw-text-white tw-m-0">
            Give a TravelShop Booking gift card
          </h1>
          <p className="tw-mt-3 tw-text-[clamp(18px,2.2vw,24px)] tw-font-semibold tw-text-white/90">
            Give the one you love
          </p>
          <p className="tw-mt-2 tw-mb-0 tw-text-[15px] tw-leading-[1.6] tw-text-white/80">
            Unforgettable travel experiences and memories to last a lifetime.
          </p>
        </div>
      </section>

      <div className="tw-container tw-mx-auto tw-max-w-[820px] tw-px-6 md:tw-px-8 tw-py-12 md:tw-py-16">
        {/* Details */}
        <div className="tw-rounded-3xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-shadow-xl tw-shadow-[#14101c]/5 tw-p-7 md:tw-p-10">
          <h2 className="tw-text-[clamp(20px,2.5vw,26px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
            Hello! We just need a few things to purchase your card
          </h2>

          <form className="tw-mt-8">
            <div className="tw-grid tw-grid-cols-1 sm:tw-grid-cols-2 tw-gap-5">
              <div>
                <label htmlFor="buyerName" className={labelClass}>
                  Name
                </label>
                <input type="text" id="buyerName" className={inputClass} />
              </div>
              <div>
                <label htmlFor="buyerSurname" className={labelClass}>
                  Surname
                </label>
                <input type="text" id="buyerSurname" className={inputClass} />
              </div>
              <div className="sm:tw-col-span-2">
                <label htmlFor="buyerEmail" className={labelClass}>
                  Your Email
                </label>
                <input
                  type="email"
                  id="buyerEmail"
                  placeholder="example@example.com"
                  className={inputClass}
                />
              </div>
            </div>

            <label className="tw-mt-5 tw-flex tw-items-center tw-gap-3 tw-text-[15px] tw-text-[#5d556c] tw-cursor-pointer">
              <input
                type="checkbox"
                className="tw-h-4 tw-w-4 tw-accent-[#854ec9] tw-cursor-pointer"
              />
              Send the card to me
            </label>

            <p className="tw-mt-6 tw-mb-0 tw-text-[14px] tw-font-semibold tw-text-[#14101c]">
              Recipient information
            </p>
            <div className="tw-mt-3 tw-grid tw-grid-cols-1 sm:tw-grid-cols-2 tw-gap-5">
              <div className="sm:tw-col-span-2">
                <label htmlFor="recipientEmail" className={labelClass}>
                  Recipient&apos;s Email
                </label>
                <input
                  type="email"
                  id="recipientEmail"
                  placeholder="example@example.com"
                  className={inputClass}
                />
              </div>
              <div>
                <label htmlFor="recipientName" className={labelClass}>
                  Name
                </label>
                <input type="text" id="recipientName" className={inputClass} />
              </div>
              <div>
                <label htmlFor="recipientSurname" className={labelClass}>
                  Surname
                </label>
                <input
                  type="text"
                  id="recipientSurname"
                  className={inputClass}
                />
              </div>
            </div>

            <p className="tw-mt-7 tw-mb-3 tw-text-[14px] tw-font-semibold tw-text-[#14101c]">
              Choose the value of the gift card:
            </p>
            <div className="tw-flex tw-flex-wrap tw-gap-2.5">
              {amountOptions.map((amount) => (
                <button
                  key={amount}
                  type="button"
                  className="tw-rounded-full tw-border tw-border-solid tw-border-[#854ec9] tw-bg-white hover:tw-bg-[#854ec9] hover:tw-text-white tw-text-[#854ec9] tw-font-semibold tw-text-[15px] tw-px-6 tw-py-2.5 tw-cursor-pointer tw-transition-colors"
                >
                  {amount}
                </button>
              ))}
            </div>

            <div className="tw-my-7 tw-flex tw-items-center tw-gap-4 tw-text-[#6b6577]">
              <span className="tw-h-px tw-flex-1 tw-bg-[#ebe7f0]" />
              <b className="tw-text-[13px]">or</b>
              <span className="tw-h-px tw-flex-1 tw-bg-[#ebe7f0]" />
            </div>

            <div>
              <label htmlFor="customAmount" className={labelClass}>
                Enter a custom amount
              </label>
              <input
                type="number"
                id="customAmount"
                defaultValue={0}
                className={inputClass}
              />
            </div>

            <div className="tw-mt-5">
              <label htmlFor="giftMessage" className={labelClass}>
                Add a personal message:
              </label>
              <textarea id="giftMessage" rows={4} className={inputClass} />
            </div>

            <div className="tw-mt-7 tw-rounded-2xl tw-bg-[#faf9fc] tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-5">
              <p className="tw-m-0 tw-text-[14px] tw-font-semibold tw-text-[#14101c]">
                Total amount to be charged
              </p>
              <div className="tw-mt-3 tw-flex tw-items-center tw-justify-between tw-text-[14px] tw-text-[#5d556c]">
                <span>TravelShop Booking Gift Card</span>
                <span className="tw-font-semibold tw-text-[#14101c]">
                  $1,000 (USD)
                </span>
              </div>
              <div className="tw-mt-3 tw-pt-3 tw-border-0 tw-border-t tw-border-solid tw-border-[#ebe7f0] tw-flex tw-items-center tw-justify-between">
                <b className="tw-text-[16px] tw-text-[#14101c]">Total</b>
                <b className="tw-text-[18px] tw-text-[#14101c]">$1,000 (USD)</b>
              </div>
            </div>

            <button
              type="submit"
              className="tw-mt-6 tw-w-full tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[16px] tw-px-7 tw-py-3.5 tw-rounded-full tw-border-0 tw-cursor-pointer tw-transition-colors"
            >
              Buy Now
            </button>
          </form>
        </div>

        {/* Payment */}
        <div className="tw-mt-8 tw-rounded-3xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-shadow-xl tw-shadow-[#14101c]/5 tw-p-7 md:tw-p-10">
          <h2 className="tw-text-[clamp(20px,2.5vw,26px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
            Payment details
          </h2>
          <form className="tw-mt-8 tw-space-y-5">
            <input
              type="text"
              inputMode="numeric"
              placeholder="Card Number"
              className={inputClass.replace("tw-mt-2 ", "")}
            />
            <div className="tw-grid tw-grid-cols-2 tw-gap-5">
              <input
                type="date"
                className={inputClass.replace("tw-mt-2 ", "")}
              />
              <input
                type="text"
                inputMode="numeric"
                placeholder="CVV"
                className={inputClass.replace("tw-mt-2 ", "")}
              />
            </div>
            <input
              type="email"
              placeholder="example@example.com"
              className={inputClass.replace("tw-mt-2 ", "")}
            />
            <div className="tw-grid tw-grid-cols-1 sm:tw-grid-cols-2 tw-gap-5">
              <input
                type="text"
                placeholder="Name"
                className={inputClass.replace("tw-mt-2 ", "")}
              />
              <input
                type="text"
                placeholder="Surname"
                className={inputClass.replace("tw-mt-2 ", "")}
              />
            </div>
            <input
              type="text"
              placeholder="+90"
              className={inputClass.replace("tw-mt-2 ", "")}
            />
            <button
              type="submit"
              className="tw-w-full tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[16px] tw-px-7 tw-py-3.5 tw-rounded-full tw-border-0 tw-cursor-pointer tw-transition-colors"
            >
              Pay Now
            </button>
          </form>
        </div>
      </div>
    </main>
  );
};

export default CustomGiftCard;
